import http from "node:http";
import { readFile, writeFile, mkdir } from "node:fs/promises";
import { existsSync } from "node:fs";
import path from "node:path";
import { randomUUID } from "node:crypto";
import { fileURLToPath } from "node:url";

const root = path.dirname(fileURLToPath(import.meta.url));
const DATA_DIR = path.join(root, "data");
const DATA_FILE = path.join(DATA_DIR, "books.json");
const PUBLIC_DIR = path.join(root, "public");
const PORT = process.env.PORT || 3000;

async function loadBooks() {
  try {
    return JSON.parse(await readFile(DATA_FILE, "utf8"));
  } catch {
    return [];
  }
}

async function saveBooks(books) {
  await mkdir(DATA_DIR, { recursive: true });
  await writeFile(DATA_FILE, JSON.stringify(books, null, 2));
}

function json(res, status, data) {
  res.writeHead(status, { "Content-Type": "application/json" });
  res.end(JSON.stringify(data));
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let body = "";
    req.on("data", (chunk) => {
      body += chunk;
      if (body.length > 1e6) req.destroy();
    });
    req.on("end", () => {
      try {
        resolve(body ? JSON.parse(body) : {});
      } catch {
        reject(new Error("Invalid JSON"));
      }
    });
    req.on("error", reject);
  });
}

const MIME = {
  ".html": "text/html",
  ".css": "text/css",
  ".js": "text/javascript",
};

async function serveFile(res, filePath) {
  try {
    const content = await readFile(filePath);
    res.writeHead(200, {
      "Content-Type": MIME[path.extname(filePath)] || "application/octet-stream",
    });
    res.end(content);
  } catch {
    res.writeHead(404, { "Content-Type": "text/plain" });
    res.end("Not found");
  }
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const books = await loadBooks();

  if (url.pathname === "/api/books" && req.method === "GET") {
    return json(res, 200, books);
  }

  if (url.pathname === "/api/books" && req.method === "POST") {
    let body;
    try {
      body = await readBody(req);
    } catch {
      return json(res, 400, { error: "Invalid JSON" });
    }
    const title = (body.title || "").trim();
    const author = (body.author || "").trim();
    if (!title || !author) {
      return json(res, 400, { error: "Title and author are required" });
    }
    const book = {
      id: randomUUID(),
      title,
      author,
      notes: (body.notes || "").trim(),
      status: "reading",
      addedAt: new Date().toISOString(),
      finishedAt: null,
    };
    books.push(book);
    await saveBooks(books);
    return json(res, 201, book);
  }

  const finishMatch = url.pathname.match(/^\/api\/books\/([^/]+)\/finish$/);
  if (finishMatch && req.method === "PATCH") {
    const book = books.find((b) => b.id === finishMatch[1]);
    if (!book) return json(res, 404, { error: "Book not found" });
    book.status = "finished";
    book.finishedAt = new Date().toISOString();
    await saveBooks(books);
    return json(res, 200, book);
  }

  const apiBookMatch = url.pathname.match(/^\/api\/books\/([^/]+)$/);
  if (apiBookMatch && req.method === "GET") {
    const book = books.find((b) => b.id === apiBookMatch[1]);
    if (!book) return json(res, 404, { error: "Book not found" });
    return json(res, 200, book);
  }

  if (url.pathname === "/" && req.method === "GET") {
    return serveFile(res, path.join(PUBLIC_DIR, "index.html"));
  }

  const pageMatch = url.pathname.match(/^\/book\/([^/]+)$/);
  if (pageMatch && req.method === "GET") {
    return serveFile(res, path.join(PUBLIC_DIR, "book.html"));
  }

  if (req.method === "GET") {
    const safePath = path.normalize(url.pathname).replace(/^(\.\.[/\\])+/, "");
    const filePath = path.join(PUBLIC_DIR, safePath);
    if (filePath.startsWith(PUBLIC_DIR) && existsSync(filePath)) {
      return serveFile(res, filePath);
    }
  }

  res.writeHead(404, { "Content-Type": "text/plain" });
  res.end("Not found");
});

server.listen(PORT, () => {
  console.log(`Book tracker running at http://localhost:${PORT}`);
});

