* {
  box-sizing: border-box;
}

body {
  font-family: system-ui, sans-serif;
  margin: 0;
  background: #f7f5f0;
  color: #222;
}

main {
  max-width: 640px;
  margin: 0 auto;
  padding: 2rem 1rem;
}

h1 {
  margin-top: 0;
}

section {
  background: #fff;
  border: 1px solid #e5e1d8;
  border-radius: 8px;
  padding: 1rem 1.25rem;
  margin-bottom: 1.25rem;
}

section h2 {
  margin-top: 0;
  font-size: 1.1rem;
}

form {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

input,
textarea {
  padding: 0.5rem;
  border: 1px solid #ccc;
  border-radius: 4px;
  font: inherit;
}

button {
  padding: 0.5rem 1rem;
  border: none;
  border-radius: 4px;
  background: #3b6ea5;
  color: #fff;
  font: inherit;
  cursor: pointer;
}

button:hover {
  background: #2f5a89;
}

.book-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.book-list li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  padding: 0.5rem 0;
  border-bottom: 1px solid #eee;
}

.book-list li:last-child {
  border-bottom: none;
}

a {
  color: #3b6ea5;
}

.author,
.status {
  color: #666;
}

.notes {
  white-space: pre-wrap;
}

